 function productPrice(p){return p.salePrice!==''&&p.salePrice!=null?`<del>NT$ ${esc(p.price)}</del> <strong>NT$ ${esc(p.salePrice)}</strong>`:p.price!==''&&p.price!=null?'NT$ '+esc(p.price):'價格洽詢';}
