 async function automations(body){const rows=await listOnce('broadcasts');const features=await capabilities();const rules=rows.filter(r=>r.type==='automation');const runtime=rows.find(r=>r.id==='_runtime');const running=millis(runtime?.lastRun)>Date.now()-36*60*60*1000;body.innerHTML=`<p class="sectionIntro">三步驟：選條件 → 寫訊息 → 勾選啟用。例：到店 30 天後問候髮況、90 天後提醒整理。到店日期請在「客戶管理 → 顧客資料 → 最後到店日期」記錄。系統每天計算，不用手動換日期標籤。</p><p class="demoBanner">${running?'雲端排程已回報執行，可啟用關懷規則。':'雲端排程尚待部署啟用。目前可儲存草稿，草稿不會自行寄送。'}</p>${rules.map(r=>`<div class="suiteRow"><div class="grow"><b>${r.kind==='birthday'?'生日祝福':r.days+(r.kind==='visit'?' 天未到店':' 天未聯絡')}</b><small>${esc(r.text)}</small><span class="pill">${r.enabled&&running?'已啟用':'草稿'}</span></div><button data-auto="${esc(r.id)}" class="linkBtn">編輯</button></div>`).join('')}<div class="settingsGroup"><h3>貼心關懷範本</h3><p class="small">先載入內容，再儲存草稿；勾選啟用才會發送。客人可在設定取消接收。</p><div class="inquiryChoices"><button data-care-template="birthday">生日祝福</button><button data-care-template="week">到店 7 天關心</button><button data-care-template="trim">到店 30 天整理提醒</button><button data-care-template="hello">90 天未聯絡問候</button></div></div><button id="newAuto">＋ 建立自動提醒（自行啟用）草稿</button>`;const edit=r=>{const d=modal('自動提醒（自行啟用）草稿',`<label>觸發條件<select id="autoKind"><option value="birthday">生日當天</option><option value="inactive">距離最後來訊</option><option value="visit" ${features.visitCare?'':'disabled'}>距離最後到店（需新版後端）</option></select></label><label>經過幾天<select id="autoDays"><option>7</option><option>14</option><option>30</option><option>60</option><option>90</option><option>180</option><option>365</option></select></label><label>訊息內容<textarea id="autoText">${esc(r.text||'')}</textarea></label><p class="small">可以使用 {姓名}，發送時會代入顧客姓名。</p><label><input id="autoEnabled" type="checkbox" ${running?'':'disabled'} ${r.enabled?'checked':''}> 啟用此規則（每日檢查）</label><button id="autoSave">儲存規則</button>`);$('autoKind').value=r.kind||'birthday';$('autoDays').value=String(r.days||30);task($('autoSave'),async()=>{const text=$('autoText').value.trim();if(!text)throw Error('請填寫內容');if($('autoKind').value==='visit'&&!features.visitCare)throw Error('到店關懷需先部署新版後端');await store('broadcasts/'+(r.id||'auto_'+crypto.randomUUID()),{type:'automation',kind:$('autoKind').value,days:Number($('autoDays').value),text,enabled:running&&$('autoEnabled').checked,updatedAt:stamp()});if(!demo)cache.delete('broadcasts');d.close();await automations(body);toast(running?'自動提醒（自行啟用）規則已儲存':'草稿已儲存，尚未啟用排程');});};const careTemplates={birthday:{kind:'birthday',text:'{姓名}，生日快樂 🎂 願你這一年有喜歡的日常，也留一點時間好好照顧自己。'},week:{kind:'visit',days:7,text:'{姓名}，上次整理頭髮後，這幾天自己整理還順手嗎？如果有哪裡不太會吹、想再調整，隨時傳訊息跟我說 😊'},trim:{kind:'visit',days:30,text:'{姓名}，最近頭髮還好整理嗎？如果瀏海或髮型有點長了，需要時再找我安排就好，不急 😊'},hello:{kind:'inactive',days:90,text:'{姓名}，好一陣子沒聊了，最近過得好嗎？有髮型或保養的小問題，都可以來問我。祝你今天順心 😊'}};body.querySelectorAll('[data-care-template]').forEach(b=>b.onclick=()=>edit({...careTemplates[b.dataset.careTemplate],enabled:false}));$('newAuto').onclick=()=>edit({});body.querySelectorAll('[data-auto]').forEach(b=>b.onclick=()=>edit(rules.find(r=>r.id===b.dataset.auto)));}

 async function feedbackForm(){const d=modal('回報與建議',`<p class="small">這裡的內容會送到店家的回報中心，不會混入聊天。</p><label>類型<select id="feedbackKind"><option>操作卡住</option><option>畫面問題</option><option>功能建議</option><option>其他</option></select></label><label>發生什麼事？<textarea id="feedbackText" maxlength="1500" placeholder="例如：從預約返回時，輸入欄跑到中間"></textarea></label><button id="feedbackSend">送出回報</button><p id="feedbackResult" role="status"></p>`);const id=crypto.randomUUID();task($('feedbackSend'),async()=>{const text=$('feedbackText').value.trim();if(!text)throw Error('請填寫回報內容');try{await setDoc(doc(db,'feedback',id),{userId:auth.currentUser.uid,name:profile?.name||'',kind:$('feedbackKind').value,text,page:document.body.dataset.page||'',createdAt:stamp(),status:'new'});d.close();toast('回報已送出，謝謝你');}catch(e){$('feedbackResult').textContent=e.code==='permission-denied'?'回報中心尚未開通，內容仍保留在這裡，請稍後再送。':'尚未送出，請稍後再試。';throw e;}});}
 async function feedbackInbox(body){body.innerHTML='<p>正在讀取回報…</p>';const rows=demo?[]:(await getDocsFromServer(query(collection(db,'feedback'),orderBy('createdAt','desc'),limit(30)))).docs.map(d=>({ref:d.ref,...d.data()}));body.innerHTML='<p class="sectionIntro">最近 30 則回報，只有開啟這一頁時讀取。</p>'+rows.map((r,i)=>`<article class="noticeCard"><div><b>${esc(r.name||'客人')} · ${esc(r.kind)}</b><p>${esc(r.text)}</p><small>${fmt(r.createdAt)} · ${esc(r.page)}</small><button data-report="${i}" ${r.status==='done'?'disabled':''}>${r.status==='done'?'已處理':'標記已處理'}</button></div></article>`).join('')+(rows.length?'':'<p class="empty">目前沒有回報。</p>');body.querySelectorAll('[data-report]').forEach(b=>task(b,async()=>{await updateDoc(rows[+b.dataset.report].ref,{status:'done'});b.textContent='已處理';b.hidden=true;}));}
 async function openTool(key){activeTool=key;if($('toolBody'))$('toolBody').dataset.colorPage=key;roomUnsub?.();roomUnsub=null;contentUnsub?.();contentUnsub=null;const names={switches:'功能開關',approvals:'新客加入審核',feedback:'客人回報',customers:'顧客資料庫',tags:'標籤庫',broadcast:'群發訊息',notice:'公告・休假',board:'布告欄',gallery:'商品管理',theme:'外觀・動態主題',stickers:'貼圖管理',settings:'店家設定',autoreply:'常見問題回覆',welcome:'加入歡迎語',booking:'預約管理',automation:'自動提醒（自行啟用）',phrases:'常用訊息設定',designers:'設計師管理'};$('toolTitle').textContent=names[key]||'店家管理';const body=$('toolBody');body.innerHTML='<p>載入中…</p>';try{if(key==='approvals')await approvalPage(body);else if(key==='feedback')await feedbackInbox(body);else if(key==='stickers')await stickerEditor(body);else if(key==='tags')await tagLibrary(body);else if(key==='customers')await customerPage(body);else if(key==='broadcast')await broadcast(body);else if(key==='gallery')await products(body,true);else if(key==='notice')await calendar(body,true);else if(key==='board')await boardEditor(body);else if(key==='booking')body.innerHTML='<p>預約由聊天室回覆確認，已移除預約紀錄管理。</p>';else if(key==='theme')await themeSettings(body);else if(key==='automation')await automations(body);else await settings(body,key);}catch(e){body.innerHTML=`<p class="suiteStatus">無法載入：${esc(e.message)}</p><button id="retryTool">重試</button>`;$('retryTool').onclick=()=>openTool(key);}}
 async function page(id){if(!admin){requestAnimationFrame(()=>{updateHeader(id);renderNotice();});}if(!['chat','adminChat'].includes(id))hideGreeting();if(!admin&&['info','gallery','booking','profile','preferences','featureDetail'].includes(id))$(id).innerHTML='<p role="status">正在讀取…</p>';if(!admin)for(const key of ['info','gallery','booking','profile','preferences','featureDetail'])if(key!==id)$(key).replaceChildren();contentUnsub?.();contentUnsub=null;if(id!=='chat'&&id!=='adminChat'){roomUnsub?.();roomUnsub=null;clearTimeout(receiptTimer);}try{if(admin&&auth.currentUser&&!demo){if(!pendingStop)pendingStop=onSnapshot(query(collection(db,'users'),where('status','==','pending'),limit(500)),snapshot=>{const count=snapshot.size;badge(document.querySelector('[data-tool=approvals]'),count,'位待核准新客',count===500);badge(document.querySelector('[data-admin-page=adminHome]'),count,'位待核准新客',count===500);appPending(count);let alert=$('newCustomerAlert');if(!alert){alert=document.createElement('button');alert.id='newCustomerAlert';alert.className='newCustomerAlert';alert.setAttribute('aria-live','polite');$('adminHome').prepend(alert);alert.onclick=()=>ctx.openTool('approvals');}alert.hidden=!count;alert.textContent='● '+count+(count===500?'+':'')+' 位新客等待核准，點此查看';},fail);if(!unreadStop)unreadStop=onSnapshot(query(collection(db,'chats'),orderBy('updatedAt','desc'),limit(500)),{includeMetadataChanges:true},snapshot=>{const count=unreadSummary(snapshot.docs.map(d=>d.data()));badge(document.querySelector('[data-admin-page=admin]'),count,'未讀對話',snapshot.size===500);appDot(count,!snapshot.metadata.fromCache&&snapshot.size<500);unreadAlert('admin',count>0,()=>document.querySelector('[data-admin-page=admin]')?.click());},fail);await readConfig();startNotices();}if(id==='adminAnalysis'){const rows=await loadCustomers();$('adminAnalysis').innerHTML='<h2>顧客概況</h2>'+countHTML(rows)+analysisHTML(rows)+'<p class="small">'+customerScope()+'。最後來訊資料從新版開始累積，舊資料未追溯掃描全部聊天。</p>';moreCustomers($('adminAnalysis'),()=>page('adminAnalysis'));}
 if(!admin){if(id==='inbox')await homeCards(await readConfig());else if(id==='preferences')customerSettings($('preferences'));else if(id==='featureDetail'){await readConfig();await homeFeatureDetail($('featureDetail'));addBack($('featureDetail'));}else if(id==='profile')await myProfile($('profile'));else if(id==='gallery'){await products($('gallery'));watchCollection('products',id,async()=>{await products($('gallery'));addBack($('gallery'));});}else if(id==='info'){await shopInfo($('info'));polishIcons();}else if(id==='booking'){await calendar($('booking'),false,true);watchCollection('holidays',id,async()=>{await calendar($('booking'),false,true);addBack($('booking'));});}else if(id==='chat'){if(getChat())attachChat(getChat());await quickButtons();}if(['info','gallery','profile','preferences','booking'].includes(id)&&!$(id).classList.contains('hidden'))addBack($(id),id==='gallery'?'info':'inbox');}}catch(e){fail(e);const body=$(id);if(!admin&&body&&!body.classList.contains('hidden')&&['info','gallery','profile','preferences','booking','featureDetail'].includes(id)){body.innerHTML='<p role="status">暫時無法載入，請確認網路後重試。</p><button data-page-retry>重新載入</button>';body.querySelector('[data-page-retry]').onclick=()=>page(id);addBack(body);}}}
 function watchCollection(path,id,draw){if(demo||$(id).classList.contains('hidden'))return;const previousStop=contentUnsub;let signature=JSON.stringify(cache.get(path)||[]);const stop=onSnapshot(query(collection(db,path),orderBy('__name__'),limit(300)),s=>{if(s.metadata.fromCache)return;const rows=s.docs.map(d=>({id:d.id,...d.data()}));const next=JSON.stringify(rows);cache.set(path,rows);cacheTimes.set(path,Date.now());if(next===signature)return;signature=next;if(!$(id).classList.contains('hidden'))draw().catch(fail);},fail);contentUnsub=()=>{previousStop?.();stop();};}
