 async function quickButtons(){if(admin)return;const c=await readConfig();const questions=(c.quickReplies||[]).filter(r=>r.enabled!==false);const box=document.querySelector('.quickPills');box.innerHTML='<button data-booking>預約詢問</button><button data-info>店家資訊</button><button data-questions>快捷詢問</button><button data-stickers>貼圖</button>';box.querySelector('[data-booking]').onclick=()=>{document.body.dataset.returnToChat='true';showPage('booking');};box.querySelector('[data-info]').onclick=()=>{document.body.dataset.returnToChat='true';showPage('info');};box.querySelector('[data-stickers]').onclick=()=>stickerPanel();box.querySelector('[data-questions]').onclick=()=>{const d=modal('快捷詢問',`<p class="small">點選後放入輸入框，可修改後再傳送。</p><div class="questionChoices">${questions.map((q,i)=>`<button data-question="${i}" class="menuCard">${esc(q.title)} <span>帶入 ›</span></button>`).join('')||'<p>店家尚未設定快捷詢問，可直接輸入訊息。</p>'}</div>`);d.querySelectorAll('[data-question]').forEach(b=>task(b,async()=>{const v=getChat();if(!v)throw Error('請先開啟聊天室');$('text').value=questions[Number(b.dataset.question)].title;d.close();toast('已放入輸入框，確認後再傳送');}));};}

 function updateChatName(){if(admin)return;const entry=$('profileEntry');if(entry)entry.innerHTML=(profile?.avatar?avatar(profile):icon('person'))+'<span>'+esc(profile?.name||'我的資料')+'</span>';const salonName=$('chatSalonName'),customerName=$('chatCustomerName');if(salonName)salonName.textContent=config?.name||defaults.name;if(customerName){const label=customerName.querySelector('#chatCustomerNameText'),picture=customerName.querySelector('.chatPersonIcon');if(label)label.textContent=profile?.name||'你';else customerName.textContent=profile?.name||'你';if(picture){picture.replaceChildren();if(typeof profile?.avatar==='string'&&profile.avatar.startsWith('data:image/')){const img=document.createElement('img');img.src=profile.avatar;img.alt='';img.loading='lazy';picture.append(img);}else{picture.textContent='♙';}}}const monogram=document.querySelector('#enterChat .salonMonogram');if(monogram)monogram.innerHTML=config?.salonAvatar?.startsWith('data:image/')?`<img src="${esc(config.salonAvatar)}" alt="">`:esc((config?.name||defaults.name).slice(0,1));}
