 function demoChat(u){
  const rows=[{id:'demo1',text:'你好，想預約下週的剪髮。',senderId:'customer',createdAt:Date.now()-60000},{id:'demo2',text:'可以的，請選擇方便的時段，我們為你安排。',senderId:ADMIN_UID,createdAt:Date.now()-30000}];let editing=null;
  modal(u.name+' · 對話範例',`<p class="demoBanner">本機互動範例，不會寄送真實訊息。</p><div id="demoMessages"></div><div class="composer"><input id="demoText" placeholder="試打一句回覆"><button id="demoSend">傳送</button></div>`);
  const draw=()=>{$('demoMessages').innerHTML=rows.map(m=>messageHTML(m,ADMIN_UID,Date.now())).join('');};draw();
  $('demoMessages').onclick=e=>{const edit=e.target.closest('[data-edit]'),retract=e.target.closest('[data-retract]');if(edit){editing=rows.find(m=>m.id===edit.dataset.edit);$('demoText').value=editing.text;$('demoSend').textContent='儲存修改';$('demoText').focus();}if(retract){const m=rows.find(m=>m.id===retract.dataset.retract);m.retracted=true;m.text='訊息已收回';draw();}};
  $('demoSend').onclick=()=>{const text=$('demoText').value.trim();if(!text)return;if(editing){editing.text=text;editing.editedAt=Date.now();editing=null;}else rows.push({id:'demo'+Date.now(),text,senderId:ADMIN_UID,createdAt:Date.now()});$('demoText').value='';$('demoSend').textContent='傳送';draw();};
 }
